#!/usr/bin/env python3
"""Independently authored expected types for existing equation declarations."""
from pathlib import Path
import json,importlib.util
ROOT=Path(__file__).resolve().parents[3]; OUT=Path(__file__).resolve().parent
T=[]
def add(mod,name,typ,scope,kind='theorem',uv=[]):
 ns='HiddenMonotonicity' if mod.startswith('HiddenMonotonicity') else ('Thesis.StoppingDAG' if mod.startswith('Thesis.StoppingDAG') else mod)
 T.append(dict(module=mod,declaration=name,expected_type=typ,open_namespaces=['HiddenMonotonicity',ns] if ns!='HiddenMonotonicity' else [ns],open_scopes=['BigOperators'],universes=uv,kind=kind,review_id='attack_hidden/lean-link-coverage',review_evidence='reports/evidence/lean-link-review/ExactTypes.lean',scope=scope))
def hm(mod,name,typ,scope,kind='theorem',uv=[]):add('HiddenMonotonicity.'+mod,'HiddenMonotonicity.'+name,typ,scope,kind,uv)
def th(mod,name,typ,scope,kind='theorem',uv=[]):add('Thesis.'+mod,'Thesis.'+name,typ,scope,kind,uv)
hm('StabilizedBackward','shiftPair','∀ {n : ℕ}, ℝ → Sensitivity n → Sensitivity n','Definition: subtract alpha times the shared sensitivity sum from both entries.','definition')
hm('StabilizedBackward','unified','∀ {n : ℕ}, Sensitivity n → Row n','Definition: exactly one half of positive minus negative partials.','definition')
hm('StabilizedBackward','shiftPair_sum','∀ {n : ℕ} (α : ℝ) (s : Sensitivity n), (shiftPair α s).1+(shiftPair α s).2 = (1-2*α) • (s.1+s.2)','Exact local bulk scaling, all real alpha.')
hm('StabilizedBackward','unified_shift','∀ {n : ℕ} (α : ℝ) (s : Sensitivity n), unified (shiftPair α s)=unified s','Local recentering preserves the half-difference.')
hm('StabilizedBackward','MaskedTrace.pull_unified','∀ {n k : ℕ} (wp wn : Matrix (Fin k) (Fin n) ℝ) (gate : Fin k → Bool) (s : Sensitivity k), unified (MaskedTrace.pull wp wn gate s)=(unified s).comp (MaskedTrace.signedMap wp wn gate)-(1/2 : ℝ) • ((s.1+s.2).comp (MaskedTrace.deadMap wp wn gate))','Actual four-block pullback rewritten as active signed Jacobian minus inactive source, arbitrary masks.')
hm('AffineReadout','MaskedTrace.run_bulk','∀ {n m : ℕ} (tr : MaskedTrace n m) (α : ℕ → ℝ) (seed : Sensitivity m), (tr.run α seed).1+(tr.run α seed).2=tr.bulkCoefficient α • ((seed.1+seed.2).comp tr.absMap)','Arbitrary terminal affine partial seed; readout shift belongs in seed, each backbone state shifted once.')
hm('StabilizedBackward','MaskedTrace.bulkCoefficient_product','∀ {n m : ℕ} (tr : MaskedTrace n m) (α : ℕ → ℝ), tr.bulkCoefficient α=∏ i ∈ Finset.range (tr.depth+1), (1-2*α i)','Exact finite product including current and terminal hidden states.')
hm('AffineChunk','affineChunk','∀ {n k : ℕ}, Matrix (Fin k) (Fin n) ℝ → Matrix (Fin k) (Fin n) ℝ → Vec k → Vec k → PairVec n → PairVec k','Definition: both signed affine streams and split biases, no terminal activation.','definition')
hm('OriginalTrace','preactivation_difference','∀ {n k : ℕ} (wp wn : Matrix (Fin k) (Fin n) ℝ) (bp bn : Vec k) (x : PairVec n), preP wp wn x+bp-(preN wp wn x+bn)=affineLayer wp wn bp bn (x.1-x.2)','Literal split affine preactivations recover original signed affine layer.')
hm('Decomposition','mixPair','ℝ → (ℝ × ℝ) → ℝ × ℝ','Definition: exact eta max/min interpolation.','definition')
hm('Core','max_sub','∀ p n : ℝ, max p n-n=relu (p-n)','Exact scalar ReLU/max subtraction identity.')
hm('NetworkDerivative','layerFun','∀ {n k : ℕ}, Matrix (Fin k) (Fin n) ℝ → Matrix (Fin k) (Fin n) ℝ → Vec k → Vec k → PairVec n → PairVec k','Definition: hidden split max/identity layer, excludes final affine output.','definition')
hm('MaxPool','finitePool','∀ {ι : Type u} [Fintype ι] [Nonempty ι] [DecidableEq ι], ((ι → ℝ) × (ι → ℝ)) → ℝ × ℝ','Definition: max positive-plus-other-negative and total negative sum.','definition',['u'])
hm('Chunks','multiplicative_split_correct','∀ p q r s : ℝ, (p*r+q*s)-(p*s+q*r)=(p-q)*(r-s)','Exact signed two-factor product.')
th('StoppingDecomposition','StoppingDecomposition.stopPair','(ℝ × ℝ) → ℝ × ℝ','Definition: common strict-positive difference gate, stopping at ties.','definition')
th('StoppingDecomposition','StoppingDecomposition.stopLayer','∀ {n k : ℕ}, Matrix (Fin k) (Fin n) ℝ → Matrix (Fin k) (Fin n) ℝ → Vec k → Vec k → PairVec n → PairVec k','Definition: exact stopping affine recursion on both streams.','definition')
th('GeneralRegularization','GeneralRegularization.pairWith','Regularizer → (ℝ → ℝ) → (ℝ × ℝ) → ℝ × ℝ','Definition: chosen-policy cost in positive stream; optimizer premise belongs to validity theorem.','definition')
th('GeneralRegularization','GeneralRegularization.entropyRegularizer','∀ θ : ℝ, 0<θ → Regularizer','Definition: actual negative binary entropy on [0,1].','definition')
th('GeneralRegularization','GeneralRegularization.hardGate_optimal','∀ z : ℝ, hardGate z ∈ Set.Icc (0 : ℝ) 1 ∧ IsMaxOn (objective zeroRegularizer z) (Set.Icc 0 1) (hardGate z)','Strict-positive zero-cost maximizing selection includes ties.')
th('Regularization','Regularization.softSplit','ℝ → ℝ → ℝ → ℝ × ℝ','Definition: sigmoid-times-positive plus active entropy, sigmoid-times-negative.','definition')
th('Regularization','Regularization.entropy_gate_value','∀ (θ z : ℝ) (hθ : 0<θ), gate θ z*z+θ*Real.binEntropy (gate θ z)=softplus θ z','Binary Legendre identity at sigmoid policy.')
th('ReferencePolicy','ReferencePolicy.reference_log_policy','∀ {A : Type u} [Fintype A] (ρ u : A → ℝ) (hu : ∀ i,0<u i), referencePolicy 1 ρ (fun i => Real.log (u i))=(fun i => ρ i*u i/∑ j,ρ j*u j)','Positive-contribution formula only; zeros use AttentionReference.','theorem',['u'])
th('ReferencePolicy','ReferencePolicy.reference_policy_value','∀ {A : Type u} [Fintype A] [Nonempty A] (θ : ℝ) (ρ q : A → ℝ) (hθ : 0<θ) (hρ : ∀ i,0<ρ i), (∑ i,referencePolicy θ ρ q i*q i)-θ*kl (referencePolicy θ ρ q) ρ=referenceValue θ ρ q','Real-score full-support optimizer attains log partition.','theorem',['u'])
th('Games','Games.pixelDisagreement_formula','∀ {X : Type u} {Y : Type v} [Fintype X] [Fintype Y] [DecidableEq Y] (p q : X → ℝ) (terminal : X → Y) (y : Y), pixelDisagreement p q terminal y=((∑ x,if terminal x=y then p x else 0)+(∑ x,if terminal x=y then q x else 0))/2-∑ x,if terminal x=y then Real.sqrt (p x*q x) else 0','Exact terminal-fibre disagreement formula on whole trajectories.','theorem',['u','v'])
th('Games','Games.pixelDisagreement_total','∀ {X : Type u} {Y : Type v} [Fintype X] [Fintype Y] [DecidableEq Y] (p q : X → ℝ) (terminal : X → Y) (hp1 : ∑ x,p x=1) (hq1 : ∑ x,q x=1), (∑ y,pixelDisagreement p q terminal y)=1-overlap p q','Actual finite terminal-fibre total; normalized path laws supply probability premises.','theorem',['u','v'])
th('Games','Games.overlap_le_one','∀ {S : Type u} [Fintype S] (p q : S → ℝ) (hp : ∀ s,0≤p s) (hq : ∀ s,0≤q s) (hp1 : ∑ s,p s=1) (hq1 : ∑ s,q s=1), overlap p q≤1','Finite probability overlap upper bound.','theorem',['u'])
th('Games','Games.overlap_nonneg','∀ {S : Type u} [Fintype S] (p q : S → ℝ), 0≤overlap p q','Finite overlap nonnegativity.','theorem',['u'])
th('RoutingSupport','RoutingSupport.sourceLayer','∀ {n k : ℕ}, Matrix (Fin k) (Fin n) ℝ → Matrix (Fin k) (Fin n) ℝ → Vec k → Vec k → ℝ → ℝ → ℝ → Vec n → Matrix (Fin k) (Fin n) ℝ','Definition: literal ungated alpha-beta epsilon redistribution matrix; raw signed inputs and biases.','definition')
th('RoutingSupport','RoutingSupport.sourceLRP','∀ {n m : ℕ}, ℝ → ℝ → ℝ → Network n m → Vec n → Vec m → Vec n','Definition: full source recurrence with arbitrary output relevance.','definition')

th('Games','Games.pathLaw','∀ {S : Type}, (n : ℕ) → (ℕ → S → S → ℝ) → S → Paths S n → ℝ','Definition: product of fixed-length transition probabilities from a fixed root; absorbing cemetery padding is explicit in its use.','definition')
th('Games','Games.backwardDP','∀ {S : Type} [Fintype S], ℕ → (ℕ → S → S → ℝ) → (S → ℝ) → S → ℝ','Definition: finite kernel backward dynamic program with actual terminal payoff.','definition')
th('Games','Games.overlap','∀ {S : Type u} [Fintype S], (S → ℝ) → (S → ℝ) → ℝ','Definition: finite sum of square-root products.','definition',['u'])
th('Tropical','Tropical.Polynomial.eval','∀ {I : Type} [Fintype I], Polynomial I → (I → ℝ) → ℝ','Definition: finite nonempty max of actual slope dot input plus intercept.','definition')
th('Tropical','Tropical.Polynomial.newton','∀ {I : Type}, Polynomial I → Set (I → ℝ)','Definition: convex hull of actual polynomial slopes.','definition')
th('Tropical','Tropical.support','∀ {I : Type} [Fintype I], Set (I → ℝ) → (I → ℝ) → ℝ','Definition: supremum of dot products; equality with maximum requires the checked compact/nonempty support theorem.','definition')
add('Thesis.StoppingDAGPaths','Thesis.StoppingDAG.pathProbability','∀ {d n : ℕ} (c : Circuit d n), PairVec d → Fin n → Thesis.StoppingDAG.DAGPaths c → ℝ','Definition: selected shared-DAG predecessor trajectory product with explicit terminal cemetery alternatives.','definition')
add('Thesis.StoppingDAGVisits','Thesis.StoppingDAG.fullOccupation','∀ {d n : ℕ}, Circuit d n → PairVec d → Fin n → Bool → ℕ → Bool → ℝ','Definition: actual expected sum of cumulative-discount-weighted graph-node visits, including starting visit.','definition')
(ROOT/'reports/additional-link-expected-types.json').write_text(json.dumps({'version':1,'targets':T},indent=2)+'\n')
spec=importlib.util.spec_from_file_location('verify',ROOT/'formalization/scripts/verify.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
driver=m.exact_driver({'public_root':'All','targets':T},OUT)
driver=driver.replace('import All\n','\n'.join('import '+s for s in sorted({t['module'] for t in T}))+'\n')
(OUT/'ExactTypes.lean').write_text(driver)
print(len(T),'contracts')
